// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human sees and opens drafts"
// Changes: Draft facts shown in the UI – "updated by agent" and the Slovak draft count. Pure, no DOM.

import type { DraftSummary } from '#/server/projects.server'

/** An agent changed (or created) the draft since the human last viewed it. */
export const updatedByAgent = (d: Pick<DraftSummary, 'lastChangedBy' | 'revision' | 'humanViewedRevision'>) =>
  d.lastChangedBy === 'agent' && d.revision > d.humanViewedRevision

/** "1 návrh", "2 návrhy", "5 návrhov" (Slovak plural). */
export function draftCount(n: number) {
  const word = n === 1 ? 'návrh' : n >= 2 && n <= 4 ? 'návrhy' : 'návrhov'
  return `${n} ${word}`
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human edits drafts"
// Changes: Slovak names of the four parts (conflict prompt), and the part list as a sentence.
import type { PartName } from './parts'

export const PART_LABELS: Record<PartName, string> = {
  definition: 'Definícia',
  grammarRules: 'Gramatické pravidlá',
  precTable: 'Precedenčná tabuľka',
  reductionRules: 'Redukčné pravidlá',
}

/** "Definícia", "Definícia a Redukčné pravidlá", "Definícia, Gramatické pravidlá a …" */
export function partList(parts: PartName[]) {
  const names = parts.map((part) => PART_LABELS[part])
  return names.length < 2 ? (names[0] ?? '') : `${names.slice(0, -1).join(', ')} a ${names.at(-1)}`
}
